<template>
  <div class="schedule-editor">
    <div class="container">
      <h2>课程计划编辑</h2>
      
      <div class="form-section">
        <h3 class="section-title">添加计划</h3>
        <div class="form-group">
          <label for="startTime">开始时间</label>
          <input 
            type="time" 
            id="startTime" 
            v-model="newSchedule.startTime"
            class="time-input"
          />
        </div>
        
        <div class="form-group">
          <label for="endTime">结束时间</label>
          <input 
            type="time" 
            id="endTime" 
            v-model="newSchedule.endTime"
            class="time-input"
          />
        </div>
        
        <div class="form-group">
          <label for="plan">任务/课程</label>
          <input 
            type="text" 
            id="plan" 
            v-model="newSchedule.plan"
            placeholder="请输入任务或课程名称"
            class="plan-input"
            @keyup.enter="addSchedule"
          />
        </div>
        
        <button @click="addSchedule" class="add-btn">添加计划</button>
      </div>
      
      <div class="schedule-list">
        <h3>已添加的计划</h3>
        <div v-if="schedules.length === 0" class="empty-tip">
          暂无课程计划，请添加
        </div>
        <div v-else>
          <div 
            v-for="(schedule, index) in sortedSchedules" 
            :key="index"
            class="schedule-item"
          >
            <span class="time">{{ schedule.startTime }} - {{ schedule.endTime }}</span>
            <span class="plan">{{ schedule.plan }}</span>
            <button @click="removeSchedule(index)" class="remove-btn">删除</button>
          </div>
        </div>
      </div>
      
      <div class="actions">
        <button @click="loadExampleData" class="example-btn" v-if="schedules.length === 0">导入示例日程表</button>
        <button @click="goToClock" class="clock-btn">查看时钟</button>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { scheduleStorage } from '../utils/scheduleStorage'

export default {
  name: 'ScheduleEditor',
  setup() {
    const router = useRouter()
    const newSchedule = ref({
      startTime: '',
      endTime: '',
      plan: ''
    })
    const schedules = ref([])
    
    const sortedSchedules = computed(() => {
      return [...schedules.value].sort((a, b) => {
        return a.startTime.localeCompare(b.startTime)
      })
    })
    
    const loadSchedules = () => {
      schedules.value = scheduleStorage.getSchedules()
    }
    
    const addSchedule = () => {
      if (!newSchedule.value.startTime || !newSchedule.value.endTime || !newSchedule.value.plan.trim()) {
        alert('请填写完整的开始时间、结束时间和任务')
        return
      }
      
      if (newSchedule.value.startTime >= newSchedule.value.endTime) {
        alert('结束时间必须晚于开始时间')
        return
      }
      
      schedules.value.push({
        startTime: newSchedule.value.startTime,
        endTime: newSchedule.value.endTime,
        plan: newSchedule.value.plan.trim()
      })
      
      scheduleStorage.saveSchedules(schedules.value)
      
      // 触发自定义事件，通知时钟页面更新
      window.dispatchEvent(new Event('scheduleUpdated'))
      
      newSchedule.value = {
        startTime: '',
        endTime: '',
        plan: ''
      }
    }
    
    const removeSchedule = (index) => {
      const sortedIndex = sortedSchedules.value[index]
      const actualIndex = schedules.value.findIndex(
        s => s.startTime === sortedIndex.startTime && 
             s.endTime === sortedIndex.endTime && 
             s.plan === sortedIndex.plan
      )
      if (actualIndex !== -1) {
        schedules.value.splice(actualIndex, 1)
        scheduleStorage.saveSchedules(schedules.value)
        
        // 触发自定义事件，通知时钟页面更新
        window.dispatchEvent(new Event('scheduleUpdated'))
      }
    }
    
    const goToClock = () => {
      router.push('/clockDisplay')
    }
    
    const loadExampleData = () => {
      const exampleSchedules = [
        { startTime: '09:00', endTime: '10:05', plan: '数学' },
        { startTime: '10:05', endTime: '10:15', plan: '下课' },
        { startTime: '10:15', endTime: '11:35', plan: '计算机' },
        { startTime: '11:35', endTime: '14:00', plan: '下课' },
        { startTime: '14:00', endTime: '15:05', plan: '计算机' },
        { startTime: '15:05', endTime: '15:15', plan: '下课' },
        { startTime: '15:15', endTime: '16:25', plan: '数学' },
        { startTime: '16:25', endTime: '16:35', plan: '下课' },
        { startTime: '16:35', endTime: '17:45', plan: '数学' },
        { startTime: '17:45', endTime: '19:30', plan: '下课' },
        { startTime: '19:30', endTime: '20:30', plan: '计算机' },
        { startTime: '20:30', endTime: '20:40', plan: '下课' },
        { startTime: '20:40', endTime: '21:40', plan: '数学' },
        { startTime: '21:40', endTime: '23:59', plan: '下课' }
      ]
      
      if (confirm('是否导入示例日程表？这将替换当前所有计划。')) {
        schedules.value = exampleSchedules
        scheduleStorage.saveSchedules(schedules.value)
        window.dispatchEvent(new Event('scheduleUpdated'))
      }
    }
    
    onMounted(() => {
      loadSchedules()
    })
    
    return {
      newSchedule,
      schedules,
      sortedSchedules,
      addSchedule,
      removeSchedule,
      goToClock,
      loadExampleData
    }
  }
}
</script>

