<template>
  <div class="clock-display" @click="toggleFullscreen">
    <div class="current-time">{{ currentTime }}</div>
    <div class="current-schedule" v-if="currentSchedule">
      <div class="schedule-label">当前任务</div>
      <div class="schedule-content">{{ currentSchedule.plan }}</div>
      <div class="schedule-time">{{ currentSchedule.startTime }} - {{ currentSchedule.endTime }}</div>
    </div>
    <div class="no-schedule" v-else>
      <div class="no-schedule-text">暂无课程安排</div>
    </div>
    
    <!-- 菜单按钮 -->
    <div class="menu-container" @click.stop>
      <button class="menu-btn" @click="showMenu = !showMenu">
        <el-icon :size="24"><Setting /></el-icon>
      </button>
      
      <div v-if="showMenu" class="menu-dropdown">
        <div class="menu-item" @click="goToEditor">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M19 12H5M12 19l-7-7 7-7"/>
          </svg>
          <span>返回编辑</span>
        </div>
        <div class="menu-item" @click="openSettings">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
            <circle cx="12" cy="12" r="3"></circle>
            <path d="M12 1v6m0 6v6m11-7h-6m-6 0H1"/>
          </svg>
          <span>铃声设置</span>
        </div>
      </div>
    </div>
    
    <!-- 铃声提醒弹窗 -->
    <div v-if="showAlarmDialog" class="alarm-modal" @click.stop>
      <div class="alarm-content">
        <div class="alarm-icon">
          <svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M22 17H2a3 3 0 0 0 3-3V9a7 7 0 0 1 14 0v5a3 3 0 0 0 3 3zm-8.27 4a2 2 0 0 1-3.46 0"></path>
          </svg>
        </div>
        <h2 class="alarm-title">时间提醒</h2>
        <div class="alarm-time">{{ currentTime }}</div>
        <div class="alarm-schedule" v-if="alarmSchedule">
          <p class="alarm-plan">{{ alarmSchedule.plan }}</p>
          <p class="alarm-duration">{{ alarmSchedule.startTime }} - {{ alarmSchedule.endTime }}</p>
        </div>
        <button class="alarm-confirm-btn" @click="stopAlarm">我知道了</button>
      </div>
    </div>
    
    <!-- 设置弹窗 -->
    <div v-if="showSettings" class="settings-modal" @click="showSettings = false">
      <div class="settings-content" @click.stop>
        <div class="settings-header">
          <h3>铃声设置</h3>
          <button class="close-btn" @click="showSettings = false">×</button>
        </div>
        
        <div class="settings-body">
          <div class="setting-item">
            <label>
              <input 
                type="checkbox" 
                v-model="settings.enabled"
                @change="saveSettings"
              />
              启用铃声提醒
            </label>
          </div>
          
          <div class="setting-item" v-if="settings.enabled">
            <label>音量: {{ Math.round(settings.volume * 100) }}%</label>
            <input 
              type="range" 
              min="0" 
              max="1" 
              step="0.1"
              v-model.number="settings.volume"
              @input="saveSettings"
              class="volume-slider"
            />
          </div>
          
          <div class="setting-item" v-if="settings.enabled">
            <label>铃声类型</label>
            <select v-model="settings.soundType" @change="saveSettings" class="sound-select">
              <option value="beep">轻柔提示音</option>
              <option value="chime">钟琴音乐</option>
              <option value="bell">柔和铃声</option>
            </select>
          </div>
          
          <div class="setting-item" v-if="settings.enabled">
            <button @click="testAlarm" class="test-btn">测试铃声</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { scheduleStorage } from '../utils/scheduleStorage'
import { alarmSettings } from '../utils/alarmSettings'
import { Setting } from '@element-plus/icons-vue'

export default {
  name: 'ClockDisplay',
  components: {
    Setting
  },
  setup() {
    const router = useRouter()
    const currentTime = ref('')
    const currentSchedule = ref(null)
    const schedules = ref([])
    const lastRungSchedule = ref(null)
    const showSettings = ref(false)
    const showMenu = ref(false)
    const showAlarmDialog = ref(false)
    const alarmSchedule = ref(null)
    const settings = ref(alarmSettings.getSettings())
    let audioContext = null
    let beepInterval = null
    
    const updateTime = () => {
      const now = new Date()
      const hours = String(now.getHours()).padStart(2, '0')
      const minutes = String(now.getMinutes()).padStart(2, '0')
      const seconds = String(now.getSeconds()).padStart(2, '0')
      currentTime.value = `${hours}:${minutes}:${seconds}`
      
      matchSchedule(`${hours}:${minutes}`)
      checkAlarm(`${hours}:${minutes}`)
    }
    
    const matchSchedule = (timeStr) => {
      if (schedules.value.length === 0) {
        currentSchedule.value = null
        return
      }
      
      const nowMinutes = timeToMinutes(timeStr)
      let matched = null
      
      for (const schedule of schedules.value) {
        const startMinutes = timeToMinutes(schedule.startTime)
        const endMinutes = timeToMinutes(schedule.endTime)
        
        if (nowMinutes >= startMinutes && nowMinutes < endMinutes) {
          matched = schedule
          break
        }
      }
      
      currentSchedule.value = matched
    }
    
    const timeToMinutes = (timeStr) => {
      const [hours, minutes] = timeStr.split(':').map(Number)
      return hours * 60 + minutes
    }
    
    // 初始化音频上下文
    const initAudioContext = () => {
      if (!audioContext) {
        const AudioContext = window.AudioContext || window.webkitAudioContext
        if (AudioContext) {
          audioContext = new AudioContext()
        }
      }
      if (audioContext && audioContext.state === 'suspended') {
        audioContext.resume()
      }
    }
    
    // 停止提示音
    const stopBeepSound = () => {
      if (beepInterval) {
        clearInterval(beepInterval)
        beepInterval = null
      }
    }
    
    // 使用 Web Audio API 生成不同类型的提示音
    const playBeepSound = () => {
      try {
        initAudioContext()
        if (!audioContext) return
        
        // 先清除之前的定时器
        stopBeepSound()
        
        // 根据设置选择不同的音调
        const soundConfig = {
          beep: { frequency: 800, duration: 0.3 },
          chime: { frequency: 1200, duration: 0.5 },
          bell: { frequency: 600, duration: 0.6 }
        }
        
        const config = soundConfig[settings.value.soundType] || soundConfig.chime
        
        // 播放一次的函数
        const playOnce = () => {
          const oscillator = audioContext.createOscillator()
          const gainNode = audioContext.createGain()
          
          oscillator.connect(gainNode)
          gainNode.connect(audioContext.destination)
          
          oscillator.frequency.value = config.frequency
          oscillator.type = 'sine'
          
          const now = audioContext.currentTime
          gainNode.gain.setValueAtTime(settings.value.volume, now)
          gainNode.gain.exponentialRampToValueAtTime(0.01, now + config.duration)
          
          oscillator.start(now)
          oscillator.stop(now + config.duration)
        }
        
        playOnce() // 立即播放一次
        
        // 每秒重复一次
        beepInterval = setInterval(() => {
          if (!showAlarmDialog.value) {
            stopBeepSound()
            return
          }
          playOnce()
        }, 1000)
        
      } catch (error) {
        console.error('Web Audio API 播放失败:', error)
      }
    }
    
    const playAlarmSound = () => {
      if (!settings.value.enabled) return
      playBeepSound()
    }
    
    const stopAlarm = () => {
      // 停止提示音
      stopBeepSound()
      
      // 关闭弹窗
      showAlarmDialog.value = false
      alarmSchedule.value = null
    }
    
    const testAlarm = () => {
      initAudioContext() // 用户交互时初始化音频
      alarmSchedule.value = {
        plan: '测试铃声',
        startTime: currentTime.value.substring(0, 5),
        endTime: '--:--'
      }
      showAlarmDialog.value = true
      playAlarmSound()
    }
    
    const saveSettings = () => {
      alarmSettings.saveSettings(settings.value)
    }
    
    const checkAlarm = (timeStr) => {
      if (!settings.value.enabled || schedules.value.length === 0) {
        return
      }
      
      const nowMinutes = timeToMinutes(timeStr)
      
      schedules.value.forEach(schedule => {
        const startMinutes = timeToMinutes(schedule.startTime)
        
        if (nowMinutes === startMinutes) {
          const scheduleKey = `${schedule.startTime}-${schedule.endTime}-${schedule.plan}`
          if (lastRungSchedule.value !== scheduleKey) {
            lastRungSchedule.value = scheduleKey
            alarmSchedule.value = schedule
            showAlarmDialog.value = true
            playAlarmSound()
          }
        } else {
          const scheduleKey = `${schedule.startTime}-${schedule.endTime}-${schedule.plan}`
          if (lastRungSchedule.value === scheduleKey && nowMinutes > startMinutes + 1) {
            lastRungSchedule.value = null
          }
        }
      })
    }
    
    const loadSchedules = () => {
      schedules.value = scheduleStorage.getSchedules()
    }
    
    const toggleFullscreen = () => {
      initAudioContext() // 用户点击时初始化音频
      if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().catch(err => {
          console.log('无法进入全屏模式:', err)
        })
      }
    }
    
    const goToEditor = () => {
      showMenu.value = false
      router.push('/clock')
    }
    
    const openSettings = () => {
      showMenu.value = false
      showSettings.value = true
    }
    
    let timer = null
    
    onMounted(() => {
      settings.value = alarmSettings.getSettings()
      
      window.addEventListener('alarmSettingsUpdated', () => {
        settings.value = alarmSettings.getSettings()
      })
      
      loadSchedules()
      updateTime()
      timer = setInterval(() => {
        updateTime()
        if (Math.floor(Date.now() / 1000) % 10 === 0) {
          loadSchedules()
        }
      }, 1000)
      
      window.addEventListener('storage', loadSchedules)
      window.addEventListener('scheduleUpdated', loadSchedules)
      
      const handleClickOutside = (e) => {
        if (showSettings.value && !e.target.closest('.settings-content') && !e.target.closest('.menu-btn')) {
          showSettings.value = false
        }
        if (showMenu.value && !e.target.closest('.menu-container')) {
          showMenu.value = false
        }
      }
      document.addEventListener('click', handleClickOutside)
      
      // 页面加载时尝试初始化音频（可能会失败，需要用户交互）
      document.addEventListener('click', initAudioContext, { once: true })
    })
    
    onUnmounted(() => {
      if (timer) {
        clearInterval(timer)
      }
      window.removeEventListener('storage', loadSchedules)
      window.removeEventListener('scheduleUpdated', loadSchedules)
      
      // 清理音频资源
      stopBeepSound()
      
      if (audioContext) {
        audioContext.close()
      }
    })
    
    return {
      currentTime,
      currentSchedule,
      showSettings,
      showMenu,
      showAlarmDialog,
      alarmSchedule,
      settings,
      toggleFullscreen,
      goToEditor,
      openSettings,
      testAlarm,
      saveSettings,
      stopAlarm
    }
  }
}
</script>


