const SETTINGS_KEY = 'alarm_settings'

const defaultSettings = {
  volume: 0.5, // 音量 0-1
  enabled: true, // 是否启用铃声
  soundType: 'beep', // 铃声类型: 'beep', 'chime', 'bell'
  frequency: 5000 // 频率（Hz）
}

export const alarmSettings = {
  getSettings() {
    try {
      const data = localStorage.getItem(SETTINGS_KEY)
      if (data) {
        const settings = JSON.parse(data)
        // 合并默认设置，确保所有字段都存在
        return { ...defaultSettings, ...settings }
      }
      return defaultSettings
    } catch (error) {
      console.error('读取铃声设置失败:', error)
      return defaultSettings
    }
  },
  
  saveSettings(settings) {
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings))
      // 触发设置更新事件
      window.dispatchEvent(new Event('alarmSettingsUpdated'))
    } catch (error) {
      console.error('保存铃声设置失败:', error)
    }
  },
  
  getDefaultSettings() {
    return { ...defaultSettings }
  }
}

