import { createRouter, createWebHashHistory } from 'vue-router'
import ScheduleEditor from '../views/ScheduleEditor.vue'
import ClockDisplay from '../views/ClockDisplay.vue'

const routes = [
  {
    path: '/',
    redirect: '/clock'
  },
  {
    path: '/clock',
    name: 'ScheduleEditor',
    component: ScheduleEditor
  },
  {
    path: '/clockDisplay',
    name: 'ClockDisplay',
    component: ClockDisplay
  }
]

const router = createRouter({
  history: createWebHashHistory(process.env.BASE_URL),  // ⚠️ 使用环境变量
  routes
})

export default router
